INSERT INTO service_catalog(id,category,icon,title_en,title_ne,description_en,description_ne,note_en,note_ne,items_json,sort_order) VALUES('government','government','building','Government & documents','सरकारी सेवा तथा कागजात','A little guidance for the important paperwork.','महत्त्वपूर्ण कागजी प्रक्रियामा सहज मार्गदर्शन।','Some services require your personal attendance, biometrics or original documents. We explain the official process; we cannot issue documents or guarantee approval.','केही सेवामा स्वयं उपस्थित हुनुपर्ने, बायोमेट्रिक वा सक्कल कागजात आवश्यक हुन सक्छ। हामी प्रक्रियामा सहयोग गर्छौँ; कागजात जारी गर्ने वा स्वीकृतिको ग्यारेन्टी गर्ने अधिकार हामीसँग छैन।','[["Passport application assistance","राहदानी आवेदन सहयोग"],["PAN registration guidance","PAN दर्ता मार्गदर्शन"],["Citizenship process guidance","नागरिकता प्रक्रियामा मार्गदर्शन"],["Voter registration & corrections","मतदाता दर्ता तथा विवरण सच्याउने सहयोग"]]',0) ON CONFLICT(id) DO NOTHING;
INSERT INTO service_catalog(id,category,icon,title_en,title_ne,description_en,description_ne,note_en,note_ne,items_json,sort_order) VALUES('utilities','utilities','bolt','Bills & utility payments','बिल तथा उपयोगिता भुक्तानी','Keep everyday essentials running smoothly.','दैनिक आवश्यक सेवाको भुक्तानी सहज बनाउनुहोस्।','We confirm your provider, bill details and total amount before processing. Never share a bank PIN, password or OTP.','भुक्तानीअघि सेवा प्रदायक, बिल विवरण र कुल रकम पुष्टि गरिन्छ। बैंक PIN, पासवर्ड वा OTP नदिनुहोस्।','[["Electricity bill assistance","विद्युत् बिल भुक्तानी सहयोग"],["Water bill assistance","खानेपानी बिल भुक्तानी सहयोग"],["Internet & broadband bills","इन्टरनेट तथा ब्रोडब्यान्ड बिल"]]',1) ON CONFLICT(id) DO NOTHING;
INSERT INTO service_catalog(id,category,icon,title_en,title_ne,description_en,description_ne,note_en,note_ne,items_json,sort_order) VALUES('travel','travel','ticket','Tickets & travel','टिकट तथा यात्रा','Help planning your next journey, near or far.','नजिक वा टाढाको यात्राको तयारीमा सहयोग।','Availability, fares, routes, cancellation terms and identity requirements depend on the operator. Tickets are confirmed only after the provider confirms the booking.','टिकट उपलब्धता, भाडा, रुट, रद्द गर्ने नियम र परिचयपत्रको आवश्यकता सम्बन्धित प्रदायकमा निर्भर हुन्छ। प्रदायकको पुष्टि भएपछि मात्र बुकिङ निश्चित हुन्छ।','[["Bus ticket booking","बस टिकट बुकिङ"],["Airline booking assistance","हवाई टिकट बुकिङ सहयोग"],["Event tickets","कार्यक्रमका टिकट"],["Train booking enquiries","रेल टिकटसम्बन्धी जानकारी"]]',2) ON CONFLICT(id) DO NOTHING;
INSERT INTO service_catalog(id,category,icon,title_en,title_ne,description_en,description_ne,note_en,note_ne,items_json,sort_order) VALUES('banking','banking','wallet','Banking & wallet guidance','बैंकिङ तथा वालेट मार्गदर्शन','Understand the steps. Stay in control of your money.','प्रक्रिया बुझ्नुहोस्। आफ्नो रकमको नियन्त्रण आफैँ राख्नुहोस्।','Guidance only; we are not a bank or investment adviser. Complete sensitive authentication yourself through your provider. We never request passwords, PINs or OTPs.','हामी मार्गदर्शन गर्छौँ; बैंक वा लगानी सल्लाहकार होइनौँ। संवेदनशील प्रमाणीकरण सम्बन्धित प्रदायकमार्फत आफैँ गर्नुहोस्। हामी पासवर्ड, PIN वा OTP माग्दैनौँ।','[["Mobile banking setup guidance","मोबाइल बैंकिङ सेटअप मार्गदर्शन"],["Digital wallet setup","डिजिटल वालेट सेटअप"],["Bank account opening guidance","बैंक खाता खोल्ने मार्गदर्शन"],["Remittance process assistance","रेमिट्यान्स प्रक्रियामा सहयोग"]]',3) ON CONFLICT(id) DO NOTHING;
INSERT INTO service_catalog(id,category,icon,title_en,title_ne,description_en,description_ne,note_en,note_ne,items_json,sort_order) VALUES('education','education','book','Education & applications','शिक्षा तथा आवेदन','Give your next opportunity a confident start.','नयाँ अवसरका लागि आत्मविश्वासका साथ तयारी गर्नुहोस्।','Eligibility, deadlines, supporting documents and decisions are set by the institution. You review and confirm all information before submission.','योग्यता, समयसीमा, आवश्यक कागजात र निर्णय सम्बन्धित संस्थाले तय गर्छ। आवेदनअघि सबै विवरण तपाईंले जाँचेर पुष्टि गर्नुहुन्छ।','[["School & college admissions","विद्यालय तथा कलेज भर्ना"],["Scholarship applications","छात्रवृत्ति आवेदन"],["SEE / NEB form assistance","SEE / NEB फाराम सहयोग"],["University application guidance","विश्वविद्यालय आवेदन मार्गदर्शन"]]',4) ON CONFLICT(id) DO NOTHING;
INSERT INTO service_catalog(id,category,icon,title_en,title_ne,description_en,description_ne,note_en,note_ne,items_json,sort_order) VALUES('other','other','chat','Something else?','अन्य सहयोग चाहिएको छ?','Tell us what you need. We will check how we can help.','आफ्नो आवश्यकता बताउनुहोस्। सहयोग गर्न सकिन्छ कि जाँच गर्छौँ।','Our team confirms whether your request is supported before accepting work. We do not assist with false documents, fraud or unlawful applications.','काम स्वीकार गर्नुअघि सेवा उपलब्ध छ कि टोलीले पुष्टि गर्छ। नक्कली कागजात, ठगी वा गैरकानुनी आवेदनमा सहयोग गरिँदैन।','[["Other online forms","अन्य अनलाइन फाराम"],["Portal registration guidance","पोर्टल दर्ता मार्गदर्शन"],["Help understanding a process","प्रक्रिया बुझ्न सहयोग"]]',5) ON CONFLICT(id) DO NOTHING;
